  gorsel: `<table class="tablo"><tr><th>Ürün</th><th>Kilogram fiyatı (TL)</th></tr><tr><td>Domates</td><td>40</td></tr><tr><td>Biber</td><td>55</td></tr><tr><td>Salatalık</td><td>30</td></tr><tr><td>Patlıcan</td><td>45</td></tr><tr><td>Havuç</td><td>25</td></tr></table>`,
  secenekler: [
    "Domates ve salatalık",
    "Biber ve patlıcan",
    "Salatalık ve havuç",
    "Patlıcan ve havuç"
  ],
