  gorsel: `<svg viewBox="0 0 560 340" role="img" aria-label="Aylık harçlığın harcama dağılımı daire grafiği"><text x="20" y="26" font-size="16" font-weight="bold" fill="currentColor">Grafik: Aylık harçlığın harcama dağılımı (400 TL)</text><path d="M280,185 L280,85 A100,100 0 0 1 360.9,126.22 Z" fill="var(--vurgu)" stroke="currentColor" stroke-width="2"/><path d="M280,185 L360.9,126.22 A100,100 0 0 1 280,285 Z" fill="var(--dolgu)" stroke="currentColor" stroke-width="2"/><path d="M280,185 L280,285 A100,100 0 0 1 180,185 Z" fill="var(--vurgu2)" stroke="currentColor" stroke-width="2"/><path d="M280,185 L180,185 A100,100 0 0 1 280,85 Z" fill="none" stroke="currentColor" stroke-width="2"/><text x="331.75" y="63.43" font-size="14" text-anchor="start" fill="currentColor">Kitap</text><text x="331.75" y="81.43" font-size="14" text-anchor="start" font-weight="bold" fill="currentColor">%15</text><text x="381.57" y="238.75" font-size="14" text-anchor="start" fill="currentColor">Yemek</text><text x="381.57" y="256.75" font-size="14" text-anchor="start" font-weight="bold" fill="currentColor">%35</text><text x="199.39" y="281.61" font-size="14" text-anchor="end" fill="currentColor">Ulaşım</text><text x="199.39" y="299.61" font-size="14" text-anchor="end" font-weight="bold" fill="currentColor">%25</text><text x="199.39" y="84.39" font-size="14" text-anchor="end" fill="currentColor">Eğlence</text><text x="199.39" y="102.39" font-size="14" text-anchor="end" font-weight="bold" fill="currentColor">%25</text></svg>`,
